const input = $json;

const allowedChannels = ['whatsapp', 'n8n_chat', 'webchat'];

if (!input.channel) throw new Error('Missing channel');
if (!allowedChannels.includes(input.channel)) throw new Error('Unsupported channel: ' + input.channel);
if (!input.phone) throw new Error('Missing phone');
if (!input.message || typeof input.message !== 'string' || input.message.trim() === '') throw new Error('Invalid message');

function fixMojibake(value) {
  const text = String(value || '');

  const latin1Fixed = text.replace(/[\u00C3\u00C2][\u0080-\u00BF]/g, (chunk) => {
    try {
      return Buffer.from(chunk, 'latin1').toString('utf8');
    } catch {
      return chunk;
    }
  });

  const replacements = [
    ['\u252c\u2510', '\u00bf'],
    ['\u252c\u00ed', '\u00a1'],
    ['\u251c\u00ed', '\u00ed'],
    ['\u251c\u00a1', '\u00e1'],
    ['\u251c\u2310', '\u00e9'],
    ['\u251c\u2502', '\u00f3'],
    ['\u251c\u2551', '\u00fa'],
    ['\u251c\u2592', '\u00f1'],
    ['\u251c\u00e2', '\u00bf'],
    ['\u251c\u00a9', '\u00e9'],
    ['\ufffd', '']
  ];

  let fixed = latin1Fixed;
  for (const [from, to] of replacements) {
    fixed = fixed.split(from).join(to);
  }
  return fixed.trim();
}

// El formato Chile (56...) solo aplica al canal whatsapp (lo exige la API
// de WhatsApp Cloud). Otros canales (webchat, n8n_chat) usan su propio
// identificador de lead como 'phone' interno, no un numero real.
let phone = input.phone.toString();
if (input.channel === 'whatsapp') {
  phone = phone.replace(/\D/g, '');
  if (!phone.startsWith('56')) throw new Error('Phone must be Chile format (56...)');
}
const message = fixMojibake(input.message);

if (!message) throw new Error('Invalid message after mojibake fix');

return [{ json: { ...input, phone, message } }];

const providerResponse = $json;
const originalInput = $("validate_outbound_input").first().json;

const hasError = providerResponse.error !== undefined;

return [{
  json: {
    ...originalInput,
    success: !hasError,
    message_sent: !hasError,
    provider_message_id: providerResponse.messages?.[0]?.id || null,
    provider_status: hasError ? "failed" : "accepted",
    provider_error: hasError ? providerResponse.error : null,
    provider_raw_response: providerResponse,
    message_type: originalInput.message_type || "text"
  }
}];

const originalInput = $("validate_outbound_input").first().json;

return [
  {
    json: {
      ...originalInput,
      success: true,
      message_sent: true,
      provider_message_id: `n8n_chat_${Date.now()}`,
      provider_status: "accepted",
      provider_error: null,
      provider_raw_response: {
        provider: "n8n_chat",
        simulated_delivery: true,
        chat_session_id: originalInput.chat_session_id || null
      },
      message_type: originalInput.message_type || "text"
    }
  }
];

const originalInput = $("validate_outbound_input").first().json;

return [
  {
    json: {
      ...originalInput,
      success: true,
      message_sent: true,
      provider_message_id: `webchat_${Date.now()}`,
      provider_status: "accepted",
      provider_error: null,
      provider_raw_response: {
        provider: "webchat_widget",
        simulated_delivery: true,
        widget_id: originalInput.execution_context?.source_metadata?.widget_id || null,
        chat_session_id: originalInput.chat_session_id || null
      },
      message_type: originalInput.message_type || "text"
    }
  }
];

